run_program <- function(lines) {
  stack <- numeric(0)
  out <- numeric(0)
  for (line in lines) {
    parts <- strsplit(line, " ")[[1]]
    op <- parts[1]
    n <- length(stack)
    if (op == "PUSH") {
      stack <- c(stack, as.numeric(parts[2]))
    } else if (op %in% c("ADD", "SUB", "MUL")) {
      top <- stack[n]
      below <- stack[n - 1]
      stack <- stack[seq_len(n - 2)]
      stack <- c(stack, switch(op, ADD = below + top, SUB = below - top, MUL = below * top))
    } else if (op == "DUP") {
      stack <- c(stack, stack[n])
    } else if (op == "SWAP") {
      stack[c(n - 1, n)] <- stack[c(n, n - 1)]
    } else if (op == "PRINT") {
      out <- c(out, stack[n])
      stack <- stack[seq_len(n - 1)]
    }
  }
  out
}
